theorem ProbabilityTheory.extracted_1.{u_5, u_2} {S : Type u_2} [inst : MeasurableSpace S]
  [inst_1 : MeasurableSingletonClass S] (μ : Measure S) [inst_2 : FiniteSupport μ] {β : Type u_5}
  [inst_3 : NormedAddCommGroup β] [inst_4 : IsFiniteMeasure μ] [inst_5 : Countable S] {f : S → β} :
  let A := μ.support;
  μ (↑A)ᶜ = 0 →
    ¬A = ∅ →
      ∀ (s₀ : S) (hs₀ : s₀ ∈ A),
        let f' := fun a => f ↑a;
        let g := fun s => if h : s ∈ A then ⟨s, h⟩ else ⟨s₀, hs₀⟩;
        f' ∘ g =ᶠ[ae μ] f → Integrable f μ := by
  apply Integrable.congr _ this
    apply Integrable.comp_measurable .of_finite
    fun_prop

theorem ProbabilityTheory.extracted_1.{u_2} {S : Type u_2} [inst : MeasurableSpace S] {μ : Measure S} {A : Finset S}
  (hA : μ (↑A)ᶜ = 0) (s : S) (hs : s ∉ A) (this : μ {s} = 0) : (((μ univ)⁻¹ • μ) {s}).toReal.negMulLog = 0 := by
  ]

theorem ProbabilityTheory.extracted_1.{u_2} {S : Type u_2} [inst : MeasurableSpace S] {μ : Measure S} {A : Finset S}
  (hA : μ (↑A)ᶜ = 0) (b : S) : b ∉ A → (((μ univ)⁻¹ • μ) {b}).toReal.negMulLog = 0 := by
  ]

theorem ProbabilityTheory.extracted_1.{u_2} {S : Type u_2} [inst : MeasurableSpace S] {μ : Measure S}
  (hμ_fin : IsFiniteMeasure μ) (hμ : NeZero μ) : Hm[(μ univ)⁻¹ • μ] = Hm[μ] := by
  simp [measureEntropy_def]

theorem ProbabilityTheory.extracted_1.{u_2} {S : Type u_2} [inst : MeasurableSpace S] {μ : Measure S}
  (hμ_fin : IsFiniteMeasure μ) (hμ : μ = 0) : Hm[(μ univ)⁻¹ • μ] = Hm[μ] := by
  simp [hμ]

